import os,subprocess,sys,tempfile
from pathlib import Path
def main():
    if len(sys.argv)!=4:raise ValueError('expected input key output')
    source,key,output=(Path(p).resolve() for p in sys.argv[1:])
    if not source.is_file() or not key.is_file() or not key.read_text().strip():raise ValueError('missing input or key')
    if output.exists() or output.is_symlink():raise ValueError('output already exists')
    descriptor,name=tempfile.mkstemp(prefix='vault-stage-',dir=output.parent);os.close(descriptor)
    stage=Path(name)
    try:
        result=subprocess.run(['ansible-vault','encrypt','--vault-id','dev@'+str(key),'--output',str(stage),str(source)],capture_output=True,timeout=15)
        if result.returncode:raise RuntimeError('Vault encryption failed')
        if not stage.read_bytes().startswith(b'$ANSIBLE_VAULT;1.2;AES256;dev\n'):raise RuntimeError('unexpected vault format')
        stage.chmod(0o600)
        os.link(stage,output)
    finally:stage.unlink(missing_ok=True)
if __name__=='__main__':
    try:main()
    except Exception:
        print('encryption rejected',file=sys.stderr);raise SystemExit(1)
```

