import os,shutil,subprocess,sys,tempfile
from pathlib import Path
def call(*args):
    result=subprocess.run(['ansible-vault',*args],capture_output=True,timeout=15)
    if result.returncode:raise RuntimeError('Vault operation failed')
    return result.stdout
def main():
    if len(sys.argv)!=4:raise ValueError('expected encrypted oldkey newkey')
    if Path(sys.argv[1]).is_symlink():raise ValueError('symlink input rejected')
    target,old,new=(Path(p).resolve() for p in sys.argv[1:])
    if not target.is_file() or target.is_symlink():raise ValueError('invalid input')
    if not old.is_file() or not new.is_file() or not new.read_text().strip():raise ValueError('invalid key')
    if old.read_text().strip()==new.read_text().strip():raise ValueError('new key must differ')
    before=target.read_bytes()
    original=call('view','--vault-id','old@'+str(old),str(target))
    with tempfile.TemporaryDirectory(prefix='rekey-stage-',dir=target.parent) as tmp:
        staged=Path(tmp)/target.name;staged.write_bytes(before);staged.chmod(0o600)
        call('rekey','--vault-id','old@'+str(old),'--new-vault-id','new@'+str(new),str(staged))
        if call('view','--vault-id','new@'+str(new),str(staged))!=original:raise ValueError('plaintext changed')
        if target.read_bytes()!=before:raise ValueError('input changed concurrently')
        staged.chmod(0o600);os.replace(staged,target)
if __name__=='__main__':
    try:main()
    except Exception:
        print('rekey rejected',file=sys.stderr);raise SystemExit(1)
```

先验证旧钥，再在暂存文件上rekey并用新钥验证明文，最后替换。Vault身份标签和解密口令需要分别检查；不更改解密后的业务配置。

